def arr(name, typ, vals, bits):
    vals = [v & ((1 << bits) - 1) for v in vals]
    rows = []
    for i in range(0, len(vals), 16):
        rows.append("        " + ", ".join('"' + format(v, '0%db' % bits) + '"' for v in vals[i:i + 16]))
    return "    constant %s : %s := (\n" % (name, typ) + ",\n".join(rows) + "\n    );"


def emit():
    txt = """-- ribboncandy_pkg.vhd -- GENERATED by ribboncandy.py; edit the generator, not this file.

library ieee;
use ieee.std_logic_1164.all;

package ribboncandy_pkg is
    type t_sin is array(0 to 1023) of std_logic_vector(11 downto 0);
    type t_bmp is array(0 to 511) of std_logic_vector(7 downto 0);
    type t_cel is array(0 to 4095) of std_logic_vector(2 downto 0);
""" + "\n".join([arr("C_RSIN", "t_sin", SIN, 12), arr("C_RBMP", "t_bmp", BMP, 8), arr("C_RCEL", "t_cel", CEL, 3)]) + """
end package ribboncandy_pkg;
"""
    with open(os.path.join(HERE, "ribboncandy_pkg.vhd"), "w") as fh:
        fh.write(txt)


if __name__ == "__main__":
    emit()
